import{z as i,x as s,o as e,c as r,q as l,j as t,D as a,d as B,s as o,S as n}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"推理预算的分配","description":"","frontmatter":{"title":"推理预算的分配","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pl-budget-allocation.md","filePath":"llm/pl-budget-allocation.md","lastUpdated":1791413859000}'),p={name:"llm/pl-budget-allocation.md"};function d(C,E,m,D,h,_){const A=s("Mermaid");return e(),r("div",null,[E[2]||(E[2]=l('<h1 id="推理预算的分配" tabindex="-1">推理预算的分配 <a class="header-anchor" href="#推理预算的分配" aria-label="Permalink to &quot;推理预算的分配&quot;">​</a></h1><div class="epigraph"><p>预算不是限速带，是分配问题：同一张 token 账单，花在宽度、深度、验证还是工具上，答案随题目难度变。</p><footer>—— Snell et al., 2024；Muennighoff et al., s1, 2025</footer></div><p><a href="/llm/pl-tool-planning">上一课</a>把工具调用写成了带预算上限的计划对象。至此本课程每个机制都是一个花钱的方向：第一课的树与回溯、第二课的逐步打分、第三课的反思轮次、第四课的分解调用、第五课的执行节点。缺口是把账合并：固定一笔推理预算，往哪花、按什么分、超了怎么办。本课写预算的记账、静态分桶与动态调整。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>宽度（\\(N\\) 条链）、深度（树、长链）、验证器调用、分解与工具次数，最终都折成同一张推理 FLOPs 账单。错误的分配有两种对称形态：全局加大 \\(N\\)——钱摊在简单题的饱和区；无差别放长链——钱烧在<a href="/llm/overthinking">过度思考</a>的复读尾部。<a href="/llm/test-time-scaling">测试时计算</a>的基本结论是最优组合随题目相对难度变：没有单一策略在所有桶上同时最优，分配本身就是策略。第二个缺口是超支行为：预算耗尽时系统做什么，决定了这条链是「体面收束」还是「截断污染下游」。</p><p><span class="marginnote">「分桶」就是把题目按预估难度装进几个筐，每个筐预配一套花法：易题筐只给一条短链，中等筐配投票加验证，难题筐才开树。就像快递分「同城 / 跨省 / 国际」走不同渠道——不是每件包裹都值得走最贵的专线，筐分错了，好策略也省钱不到点子上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记账先行：预算单位要能跨机制相加。生成 token 分「链内思维」与「最终答案」两栏，<a href="/llm/reasoning-length-control">推理长度控制</a>的结论是二者分开塑形；打分前向、工具调用、PRM 调用按固定折算率并进同一请求账户。四个闸门（深度、分支、节点数、时间）从第一课继承，全部作用在同一账户上。</p><p>静态分配按难度分桶配置：易题单链短预算，禁触发器；中题自洽加验证选链；难题开树配 PRM，反思与分解按需启用。<a href="/llm/snell-test-time">Test-time compute 综述</a>给出的量级是：按桶配策略相对盲目的 BoN 可以把效率提高数倍，小模型配计算最优能匹敌参数量大一个数量级模型的朴素解码——分配的价值不在省，在把钱挪到有边际收益的桶里。动态分配叠加在静态之上：校验通过即早停；分数门控报警时加注（开新分支、触发一轮反思）；预算字段贯穿请求，每一跳扣减。</p><p><span class="marginnote">数字实例（示意）：设单链写 2000 token。同一笔「16 倍」账单，加在易题上（\\(N=16\\) 投票）可能只把 95% 抬到 96%；挪到中等题上，\\(N=16\\) 自洽常能把 60% 附近拉高约十来个点。这就是「边际收益」的含义——同样多的 token，在中难度桶里每 1000 个都还在换分，在易题桶里早已换不动。</span></p>',10)),(e(),t(n,null,{default:a(()=>[o(A,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20LR%0A%20%20B%5B%22%E5%90%8C%E4%B8%80%E7%AC%94%E9%A2%84%E7%AE%97%E7%BF%BB%E5%80%8D%22%5D%20--%3E%20E%5B%22%E6%98%93%E9%A2%98%EF%BC%9A%E6%97%A9%E5%B7%B2%E9%A5%B1%E5%92%8C%22%5D%0A%20%20B%20--%3E%20M%5B%22%E4%B8%AD%E9%A2%98%EF%BC%9A%E8%BE%B9%E9%99%85%E6%94%B6%E7%9B%8A%E6%9C%80%E5%A4%A7%22%5D%0A%20%20B%20--%3E%20H%5B%22%E9%9A%BE%E9%A2%98%EF%BC%9A%E7%BC%BA%E7%9F%A5%E8%AF%86%EF%BC%8C%E6%94%B6%E7%9B%8A%E6%9C%89%E9%99%90%22%5D%0A%20%20E%20--%3E%20X%5B%22%E7%AD%94%E6%A1%88%E5%87%A0%E4%B9%8E%E4%B8%8D%E5%8F%98%EF%BC%8Ctoken%20%E7%99%BD%E8%8A%B1%22%5D%0A%20%20M%20--%3E%20Y%5B%22%E6%8A%95%E7%A5%A8%E4%B8%8E%E6%A0%91%E6%8B%89%E5%BC%80%E5%B7%AE%E8%B7%9D%22%5D%0A%20%20H%20--%3E%20Z%5B%22%E7%95%A5%E6%B6%A8%EF%BC%8C%E5%89%A9%E4%BD%99%E5%BA%94%E5%9B%9E%E6%B5%81%E8%AE%AD%E7%BB%83%E4%BE%A7%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=l('<p><span class="marginnote">训练侧要见过预算：把多个预算档写进 RL 采样，或用 budget forcing 在到达上限时强制收束——只靠推理期截断，模型没学过「在 \\(B\\) 内写完」，准确率会掉（s1 的预算强迫是控制手段，不是训练替代）。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>超支行为是正确性问题。预算耗尽时的默认动作是回退：从已探索候选中取当前最可信的一条，按显式的截断语义返回——<code>finish</code> 标明预算触发，调用方据此决定要不要降级重试，而不是把半截结论当完整话语写进多轮历史（停止协议的语义见<a href="/llm/stop-sequences">停用词与 stop sequences</a>）。静默截断是最坏的出口：它把系统失败伪装成模型失败，评测与用户同时被误导。</p><p><span class="marginnote">常见误区：初学者以为截断的坏处只是「没答案」，实际上更危险的是「有半截答案」——一句没有验证过的中间结论被当成完整回复写进对话历史，下一轮模型把它当已知事实继续推，错误就滚进下游。这也是为什么截断必须带显式语义标记，宁可让调用方看见失败。</span></p>',4)),(e(),t(n,null,{default:a(()=>[o(A,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%E5%B8%A6%E9%A2%84%E7%AE%97%E8%B4%A6%E6%88%B7%20B%22%5D%20--%3E%20BUCKET%7B%22%E9%9A%BE%E5%BA%A6%E5%88%86%E6%A1%B6%22%7D%0A%20%20BUCKET%20--%3E%7C%E6%98%93%7C%20EASY%5B%22%E5%8D%95%E9%93%BE%E7%9F%AD%E9%A2%84%E7%AE%97%EF%BC%8C%E7%A6%81%E8%A7%A6%E5%8F%91%E5%99%A8%22%5D%0A%20%20BUCKET%20--%3E%7C%E4%B8%AD%7C%20MID%5B%22%E8%87%AA%E6%B4%BD%20%2B%20%E9%AA%8C%E8%AF%81%E9%80%89%E9%93%BE%22%5D%0A%20%20BUCKET%20--%3E%7C%E9%9A%BE%7C%20HARD%5B%22%E6%A0%91%20%2B%20PRM%EF%BC%8C%E5%8F%8D%E6%80%9D%E6%8C%89%E9%9C%80%22%5D%0A%20%20EASY%20--%3E%20RUN%5B%22%E6%89%A7%E8%A1%8C%E4%B8%AD%E9%80%90%E8%B7%B3%E6%89%A3%E5%87%8F%22%5D%0A%20%20MID%20--%3E%20RUN%0A%20%20HARD%20--%3E%20RUN%0A%20%20RUN%20--%3E%20OUT%7B%22%E9%A2%84%E7%AE%97%E8%80%97%E5%B0%BD%3F%22%7D%0A%20%20OUT%20--%3E%7C%E5%90%A6%7C%20DONE%5B%22%E6%A0%A1%E9%AA%8C%E9%80%9A%E8%BF%87%E5%8D%B3%E6%97%A9%E5%81%9C%22%5D%0A%20%20OUT%20--%3E%7C%E6%98%AF%7C%20FALL%5B%22%E5%9B%9E%E9%80%80%E6%9C%80%E5%8F%AF%E4%BF%A1%E5%80%99%E9%80%89%EF%BC%8C%E6%98%BE%E5%BC%8F%E6%A0%87%E6%88%AA%E6%96%AD%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>推理预算有收益上限：很难的题上搜索补不齐预训练缺失的知识，桶里持续超支的题目应该回流到训练侧，而不是继续加注。摊销逻辑要分账：训练期花的 FLOPs 摊到所有请求，推理期只摊到单请求，比较「多训练 vs 多推理」时口径不能混。延迟 SLA 与离线评测不同：树与自洽的收益按吞吐算，在线按尾延迟算，同一策略在两张榜上名次不同。最后，分配策略本身要用成本-质量曲线验收：每一档声明它停在曲线的哪一段，不许只报准确率不报账单。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分配就是策略：宽度、深度、验证、工具同账核算，按难度分桶各配各的。</li><li>静态配桶加动态加注；早停与门控是节流的两个方向。</li><li>训练要见过多档预算；纯推理截断是最后闸不是控制手段。</li><li>超支走显式回退与截断语义；静默截断把系统失败伪装成模型失败。</li><li>很难题的超支回流训练侧；分配策略用成本-质量曲线验收。</li><li>出处：Snell et al., 2024；Muennighoff et al., <em>s1</em>, 2025；Yu et al., DAPO, 2025（长度塑形）。</li></ul>',4))])}const f=i(p,[["render",d]]);export{u as __pageData,f as default};
